BEGIN;SET LOCAL statement_timeout='5s';SET LOCAL lock_timeout='1s';
WITH recent AS MATERIALIZED(SELECT runid,jobid,status,return_message,start_time,end_time FROM cron.job_run_details ORDER BY runid DESC LIMIT 120)
SELECT jsonb_build_object('runs',(SELECT jsonb_agg(jsonb_build_object('runid',runid,'status',status,'message',return_message,'start',start_time,'end',end_time,'ms',extract(epoch FROM end_time-start_time)*1000)ORDER BY runid DESC)FROM recent WHERE jobid=31),'job',(SELECT jsonb_build_object('id',jobid,'name',jobname,'active',active,'schedule',schedule,'command_md5',md5(command)) FROM cron.job WHERE jobid=31),'admission',(SELECT value FROM zoi.delivery_state WHERE key='enrichment_admission_v1'),'at',clock_timestamp());COMMIT;
